const filterVisibleConversationUUIDs = `-- name: FilterVisibleConversationUUIDs :many
SELECT c.uuid FROM conversations c
WHERE c.organization_id = $1
  AND c.uuid = ANY($2::uuid[])
  AND c.deleted_at IS NULL
  AND ($3::boolean
       OR c.assignee_user_id = $4::bigint
       OR c.assignee_team_id = ANY($5::bigint[])
       OR (c.assignee_user_id IS NULL AND c.assignee_team_id IS NULL)
       OR EXISTS (SELECT 1 FROM conversation_participants vp
                  WHERE vp.organization_id = c.organization_id AND vp.conversation_id = c.id
                    AND vp.user_id = $4::bigint))
`

type FilterVisibleConversationUUIDsParams struct {
	OrganizationID int64       `json:"organization_id"`
	Uuids          []uuid.UUID `json:"uuids"`
	SeeAll         bool        `json:"see_all"`
	ViewerID       int64       `json:"viewer_id"`
	ViewerTeamIds  []int64     `json:"viewer_team_ids"`
}

// The conversations among uuids the viewer may see (search hits).
func (q *Queries) FilterVisibleConversationUUIDs(ctx context.Context, arg FilterVisibleConversationUUIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, filterVisibleConversationUUIDs,
		arg.OrganizationID,
		arg.Uuids,
		arg.SeeAll,
		arg.ViewerID,
		arg.ViewerTeamIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var uuid uuid.UUID
		if err := rows.Scan(&uuid); err != nil {
			return nil, err
		}
		items = append(items, uuid)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

