const getTagsByUUIDs = `-- name: GetTagsByUUIDs :many
SELECT id, uuid, organization_id, name, color, created_at FROM tags WHERE organization_id = $1 AND uuid = ANY($2::uuid[])
`

type GetTagsByUUIDsParams struct {
	OrganizationID int64       `json:"organization_id"`
	Uuids          []uuid.UUID `json:"uuids"`
}

func (q *Queries) GetTagsByUUIDs(ctx context.Context, arg GetTagsByUUIDsParams) ([]Tag, error) {
	rows, err := q.db.Query(ctx, getTagsByUUIDs, arg.OrganizationID, arg.Uuids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Tag{}
	for rows.Next() {
		var i Tag
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.Name,
			&i.Color,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

