const listConversations = `-- name: ListConversations :many
SELECT c.id, c.uuid, c.organization_id, c.number, c.channel_type, c.channel_instance_id, c.contact_id, c.company_id, c.subject, c.status, c.status_id, c.priority, c.source, c.assignee_user_id, c.assignee_team_id, c.custom_fields, c.external_thread_id, c.sla_policy_id, c.first_response_due_at, c.next_response_due_at, c.resolution_due_at, c.sla_breached_at, c.first_response_at, c.waiting_since, c.snoozed_until, c.resolved_at, c.closed_at, c.last_message_at, c.last_inbound_at, c.last_outbound_at, c.last_message_preview, c.last_message_direction, c.message_count, c.meta, c.created_at, c.updated_at, c.deleted_at, c.merged_into_id, c.merged_at, c.anonymized_at, c.brand_id, c.department_id, c.department_source, c.department_confidence, c.department_routed_at,
       ct.uuid AS contact_uuid, ct.name AS contact_name, ct.email AS contact_email, ct.phone AS contact_phone,
       ct.external_id AS contact_external_id, ct.verified_at AS contact_verified_at,
       co.uuid AS company_uuid, co.name AS company_name, co.external_id AS company_external_id,
       inst.uuid AS channel_instance_uuid, inst.name AS channel_instance_name,
       u.uuid AS assignee_uuid, u.name AS assignee_name, u.surname AS assignee_surname,
       tm.uuid AS team_uuid, tm.name AS team_name,
       st.uuid AS status_uuid, st.name AS status_name, st.color AS status_color,
       COALESCE((SELECT array_agg(t.uuid ORDER BY lower(t.name)) FROM conversation_tags x
                 JOIN tags t ON t.organization_id = x.organization_id AND t.id = x.tag_id
                 WHERE x.organization_id = c.organization_id AND x.conversation_id = c.id), '{}')::uuid[] AS tag_uuids,
       COALESCE((SELECT COUNT(*) FROM messages m
                 WHERE m.organization_id = c.organization_id AND m.conversation_id = c.id
                   AND m.id > COALESCE(r.last_read_message_id, 0)
                   AND m.deleted_at IS NULL
                   AND (m.sender_user_id IS NULL OR m.sender_user_id <> $1::bigint)
                   AND m.direction <> 'internal'), 0)::int AS unread_count
FROM conversations c
JOIN contacts ct ON ct.organization_id = c.organization_id AND ct.id = c.contact_id
LEFT JOIN companies co ON co.organization_id = c.organization_id AND co.id = c.company_id AND co.deleted_at IS NULL
LEFT JOIN channel_instances inst ON inst.organization_id = c.organization_id AND inst.id = c.channel_instance_id
LEFT JOIN users u ON u.id = c.assignee_user_id
LEFT JOIN teams tm ON tm.organization_id = c.organization_id AND tm.id = c.assignee_team_id
LEFT JOIN conversation_statuses st ON st.organization_id = c.organization_id AND st.id = c.status_id
LEFT JOIN conversation_reads r ON r.organization_id = c.organization_id AND r.conversation_id = c.id AND r.user_id = $1::bigint
WHERE c.organization_id = $2
 AND ($3::uuid IS NULL OR c.brand_id=$3::uuid)
  AND c.deleted_at IS NULL
  -- Team visibility (CF-44, docs/design/tenant-core.md §9): without
  -- tenant.conversations.read_all a member sees its own, its teams', the
  -- unrouted queue (no agent, no team) and the ones it participates in.
  AND ($4::boolean
       OR c.assignee_user_id = $1::bigint
       OR c.assignee_team_id = ANY($5::bigint[])
       OR (c.assignee_user_id IS NULL AND c.assignee_team_id IS NULL)
       OR EXISTS (SELECT 1 FROM conversation_participants vp
                  WHERE vp.organization_id = c.organization_id AND vp.conversation_id = c.id
                    AND vp.user_id = $1::bigint))
  AND (cardinality($6::text[]) = 0 OR c.status = ANY($6::text[]))
  AND (cardinality($7::text[]) = 0 OR c.priority = ANY($7::text[]))
  AND (cardinality($8::text[]) = 0 OR c.channel_type = ANY($8::text[]))
  AND (cardinality($9::bigint[]) = 0 OR c.channel_instance_id = ANY($9::bigint[]))
  AND ($10::text = ''
       OR ($10::text = 'me' AND c.assignee_user_id = $1::bigint)
       OR ($10::text = 'unassigned' AND c.assignee_user_id IS NULL)
       OR ($10::text = 'user' AND c.assignee_user_id = $11::bigint))
  AND ($12::bigint IS NULL OR c.assignee_team_id = $12)
  AND (NOT $13::boolean OR c.assignee_team_id IN (
        SELECT mt.team_id FROM team_members mt WHERE mt.organization_id = c.organization_id AND mt.user_id = $1::bigint))
  AND ($14::bigint IS NULL OR c.contact_id = $14)
  AND ($15::bigint IS NULL OR c.company_id = $15)
  AND (cardinality($16::bigint[]) = 0 OR EXISTS (
        SELECT 1 FROM conversation_tags x WHERE x.organization_id = c.organization_id AND x.conversation_id = c.id AND x.tag_id = ANY($16::bigint[])))
  AND (NOT $17::boolean OR EXISTS (
        SELECT 1 FROM message_mentions mm JOIN messages m2 ON m2.organization_id = mm.organization_id AND m2.id = mm.message_id
        WHERE m2.organization_id = c.organization_id AND m2.conversation_id = c.id AND mm.user_id = $1::bigint))
  AND (NOT $18::boolean OR EXISTS (
        SELECT 1 FROM messages m3
        WHERE m3.organization_id = c.organization_id AND m3.conversation_id = c.id
          AND m3.id > COALESCE(r.last_read_message_id, 0) AND m3.direction = 'in'))
  AND ($19::boolean IS NULL OR (c.sla_breached_at IS NOT NULL) = $19)
  -- CF-195: who the contact is (verified with user_hash, anonymous, or
  -- named by itself without proof).
  AND ($20::text IS NULL
       OR ($20::text = 'verified' AND ct.verified_at IS NOT NULL)
       OR ($20::text = 'anonymous' AND ct.verified_at IS NULL AND ct.name = '' AND ct.email IS NULL AND ct.phone IS NULL)
       OR ($20::text = 'self_named' AND ct.verified_at IS NULL AND (ct.name <> '' OR ct.email IS NOT NULL OR ct.phone IS NOT NULL)))
  -- CF-245: the REST API channel's own thread id.
  AND ($21::text IS NULL OR c.external_thread_id = $21::text)
  AND ($22::timestamptz IS NULL OR (
        c.sla_breached_at IS NULL AND c.status IN ('open', 'pending')
        AND LEAST(c.first_response_due_at, c.next_response_due_at, c.resolution_due_at) <= $22::timestamptz))
  AND ($23::text IS NULL
       OR c.subject ILIKE '%' || $23 || '%'
       OR c.last_message_preview ILIKE '%' || $23 || '%'
       OR ct.name ILIKE '%' || $23 || '%'
       OR ct.email ILIKE '%' || $23 || '%'
       OR ct.phone ILIKE '%' || $23 || '%'
       OR ct.external_id = $23
       OR c.number::text = $23
       OR c.uuid = ANY($24::uuid[]))
ORDER BY
  CASE WHEN $25::text = 'last_message_at' AND $26::boolean THEN c.last_message_at END DESC,
  CASE WHEN $25::text = 'last_message_at' AND NOT $26::boolean THEN c.last_message_at END ASC,
  CASE WHEN $25::text = 'created_at' AND $26::boolean THEN c.created_at END DESC,
  CASE WHEN $25::text = 'created_at' AND NOT $26::boolean THEN c.created_at END ASC,
  CASE WHEN $25::text = 'waiting_since' AND $26::boolean THEN c.waiting_since END DESC NULLS LAST,
  CASE WHEN $25::text = 'waiting_since' AND NOT $26::boolean THEN c.waiting_since END ASC NULLS LAST,
  CASE WHEN $25::text = 'priority' AND $26::boolean
       THEN CASE c.priority WHEN 'urgent' THEN 4 WHEN 'high' THEN 3 WHEN 'normal' THEN 2 ELSE 1 END END DESC,
  CASE WHEN $25::text = 'priority' AND NOT $26::boolean
       THEN CASE c.priority WHEN 'urgent' THEN 4 WHEN 'high' THEN 3 WHEN 'normal' THEN 2 ELSE 1 END END ASC,
  c.last_message_at DESC,
  c.id DESC
LIMIT $28 OFFSET $27
`

